# Hypothesis: __new__ and __init__ calls along a diamond MRO reach each base once, and build(type[B]) returns the bound subclass type.
from typing import Self, TypeVar, reveal_type


class Root:
    def __new__(cls, name: str) -> Self:
        return super().__new__(cls)

    def __init__(self, name: str) -> None:
        self.name = name


class Left(Root):
    def __init__(self, name: str) -> None:
        super().__init__(name.upper())


class Right(Root):
    def __init__(self, name: str) -> None:
        super().__init__(name + "!")


class Bottom(Left, Right):
    pass


B = TypeVar("B", bound=Root)


def build(kind: type[B], arg: str) -> B:
    return kind(arg)


item = build(Bottom, "x")
reveal_type(item)
reveal_type(build(Right, "y"))
assert item.name == "X!"
assert build(Right, "y").name == "y!"
